"""MCP server for kosha — repo + package context search and call-graph tools over stdio.
Run `kosha-mcp` from the target repo's root in its venv (e.g. `uv run kosha-mcp`).

Docs: https://vedicreader.github.io/kosha/mcp.html.md"""

import sys, threading, uuid, traceback
from datetime import datetime, timezone
from concurrent.futures import ThreadPoolExecutor
from .core import Kosha, env_pkg_versions, pkg_url as _pkg_url, _pkg_info

try: from mcp.server.fastmcp import FastMCP
except ImportError as e:
    raise ImportError("kosha-mcp needs the `mcp` package (a kosha dependency) — "
                      "reinstall kosha with `uv add --dev koshas` or `pip install koshas`") from e

# %% ../nbs/04_mcp.ipynb #c83b2bc6
mcp = FastMCP('kosha', instructions=(
    'Persistent memory of this repo and its installed packages (FTS5 + vector search + call graph). '
    'Call status first; sync if anything is stale. Before writing new code, env_context checks whether '
    'a dependency already does it; context/repo_context find existing patterns (pagerank = blast radius); '
    'node_info/short_path/api_paths answer call-graph questions; where_to_add gives file:line insertion '
    'points. Queries mix natural language with filters: package:name path:sub lang:py type:FunctionDef; '
    'package!:name hard-filters to one package.'))

_k, _root, _python, _klock = None, None, None, threading.Lock()
def _kosha():
    "Thread-safe lazy project singleton."
    global _k
    if _k is None:
        with _klock:
            if _k is None: _k = Kosha(dir=_root,python=_python)
    return _k

def _read():
    "Return Kosha when no sync writer is active."
    if _active and _jobs[_active]['state'] in ('queued','running'): raise RuntimeError(f"sync_running:{_active}")
    return _kosha()

_pool, _jlock, _jobs, _active = ThreadPoolExecutor(max_workers=1), threading.Lock(), {}, None
_now = lambda: datetime.now(timezone.utc).isoformat()

def _run_sync(jid, kw):
    global _active
    job = _jobs[jid]; job.update(state='running',started_at=_now())
    try:
        k = _kosha(); k.sync(**kw); job.update(state='succeeded',result=_jsonable(k.status()))
    except Exception as e: job.update(state='failed',error=str(e),traceback=traceback.format_exc(limit=8))
    finally:
        job['finished_at'] = _now()
        with _jlock: _active = None

def _submit_sync(kw):
    global _active
    with _jlock:
        if _active and _jobs[_active]['state'] in ('queued','running'): return _jobs[_active] | {'accepted':False}
        jid = uuid.uuid4().hex; _active = jid
        _jobs[jid] = dict(job_id=jid,state='queued',accepted=True,created_at=_now(),args=kw)
        _pool.submit(_run_sync,jid,kw)
        return _jobs[jid]

def _jsonable(o):
    'Recursively convert kosha result objects (L, sets, ...) to JSON-serializable types.'
    if isinstance(o, (set, frozenset)): return sorted(o)
    if isinstance(o, dict): return {str(k): _jsonable(v) for k, v in o.items()}
    if isinstance(o, (str, int, float, bool)) or o is None: return o
    if hasattr(o, '__iter__'): return [_jsonable(x) for x in o]
    return str(o)

# %% ../nbs/04_mcp.ipynb #f1bbab07
@mcp.tool()
def status() -> dict:
    "Index freshness plus the latest background sync job."
    out = _jsonable(_kosha().status())
    if _jobs: out['sync'] = _jsonable(_jobs[next(reversed(_jobs))])
    return out

@mcp.tool()
def sync(dir:str|None=None, pkgs:list|None=None, embed:bool=True, force:bool=False, sync_graph:bool=False) -> dict:
    "Queue a serialized background sync and immediately return its job ID."
    return _jsonable(_submit_sync(dict(dir=dir,pkgs=pkgs,embed=embed,force=force,sync_graph=sync_graph)))

@mcp.tool()
def sync_status(job_id:str|None=None) -> dict:
    "State of a sync job, or the latest job when omitted."
    if not _jobs: return {'state':'idle'}
    jid = job_id or next(reversed(_jobs))
    return _jsonable(_jobs.get(jid) or {'job_id':jid,'state':'not_found'})


