def main():
    "Run MCP over stdio, or Streamable HTTP with --http."
    global _root, _python
    args = sys.argv[1:]
    def val(flag):
        try: return args[args.index(flag)+1]
        except (ValueError,IndexError): return None
    _root, _python = val('--project'), val('--python')
    mcp.run(transport='streamable-http' if '--http' in args else 'stdio')
